# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def treeQueries(self, root: Optional[TreeNode], queries: List[int]) -> List[int]:
        heights = {}

        def dfs(node, depth):
            if not node:
                return depth - 1

            left_depth = dfs(node.left, depth + 1)
            right_depth = dfs(node.right, depth + 1)

            heights[node.val] = max(left_depth, right_depth)
            return max(left_depth, right_depth)

        dfs(root, 0)

        result = []

        for q in queries:
            max_height = 0
            max_depth = 0

            def update_max(node, depth):
                nonlocal max_height, max_depth
                if not node:
                    return

                if depth > max_depth:
                    max_depth = depth
                    max_height = heights[node.val]

                update_max(node.left, depth + 1)
                update_max(node.right, depth + 1)

            update_max(root, 0)

            result.append(max_height)

        return result

from typing import *
class Solution:
    def minOperations(self, nums: List[int], x: int) -> int:
        target = sum(nums) - x
        if target < 0:
            return -1

        prefix_sum = {0: -1}
        current_sum = 0

        for i, num in enumerate(nums):
            current_sum += num
            if current_sum - target in prefix_sum:
                return i - prefix_sum[current_sum - target]
            prefix_sum[current_sum] = i

        return -1

from typing import List

class Solution:
    def taskSchedulerII(self, tasks: List[int], space: int) -> int:
        last_seen = {}
        current_day = 0

        for task in tasks:
            if task in last_seen:
                days_since_last = current_day - last_seen[task]
                if days_since_last < space:
                    current_day += space - days_since_last

            last_seen[task] = current_day
            current_day += 1

        return current_day

class Solution:
    def countExcellentPairs(self, nums: List[int], k: int) -> int:
        from collections import Counter

        # Remove duplicates and calculate the number of set bits for each unique number
        unique_nums = list(set(nums))
        bit_counts = [bin(num).count('1') for num in unique_nums]

        # Count occurrences of each bit count
        bit_count_counter = Counter(bit_counts)

        result = 0

        # Iterate through each unique bit count
        for i in range(1, max(bit_counts) + 1):
            for j in range(i, max(bit_counts) + 1):
                if i + j >= k:
                    result += bit_count_counter[i] * bit_count_counter[j]

        return result

class Solution:
    def greatestLetter(self, s: str) -> str:
