class Solution:
    def numDecodings(self, s: str) -> int:
        MOD = 10**9 + 7

        # dp[i] represents the number of ways to decode the substring s[0:i]
        dp = [0] * (len(s) + 1)
        dp[0] = 1  # There's one way to decode an empty string

        if s[0] == '*':
            dp[1] = 9  # '*' can represent any digit from 1 to 9
        else:
            dp[1] = 1 if s[0] != '0' else 0

        for i in range(2, len(s) + 1):
            # Single digit decoding
            if s[i - 1] != '0':
                dp[i] += dp[i - 1]

            # Two digit decoding
            if i >= 2:
                two_digit = int(s[i - 2:i])
                if two_digit >= 10 and two_digit <= 26:
                    dp[i] += dp[i - 2]
                elif two_digit == 10 or two_digit == 20:
                    dp[i] += dp[i - 2]
                elif two_digit > 26:
                    continue

            # Handle '*'
            if s[i - 1] == '*':
                if i >= 2:
                    # '1*' can be '11' to '19'
                    if s[i - 2] == '1':
                        dp[i] += 9 * dp[i - 2]
                    # '2*' can be '21' to '26'
                    elif s[i - 2] == '2':
                        dp[i] += 6 * dp[i - 2]
                    # '*' can be '11' to '19' or '21' to '26'
                    else:
                        dp[i] += 15 * dp[i - 2]
                else:
                    # '*' can be '1' to '9'
                    dp[i] += 9

        return dp[-1] % MOD

