class Solution:
    def badSensor(self, sensor1: List[int], sensor2: List[int]) -> int:
        n = len(sensor1)

        for i in range(n - 1):
            if sensor1[i] != sensor2[i]:
                # Check if sensor1 is correct
                if sensor1[i:n-1] == sensor2[i+1:] and sensor1[n-1] != sensor2[i]:
                    return 2
                # Check if sensor2 is correct
                if sensor2[i:n-1] == sensor1[i+1:] and sensor2[n-1] != sensor1[i]:
                    return 1

        # If no mismatch found or unable to determine
        return -1

class Solution:
    def matrixReshape(self, mat: List[List[int]], r: int, c: int) -> List[List[int]]:
        # Check if the product of rows and columns is equal to the product of rows and columns
        if len(mat) * len(mat[0]) != r * c:
            return mat

        # Reshape the matrix
        result = []
        for i in range(r):
            temp = []
            for j in range(c):
                temp.append(mat[i][j])
            result.append(temp)

        return result

from typing import List

class Solution:
    def maximumEnergy(self, energy: List[int], k: int) -> int:
        n = len(energy)
        dp = [float('-inf')] * n

        for start in range(n):
            current_energy = 0
            for i in range(start, n, k):
                current_energy += energy[i]
                dp[i] = max(dp[i], current_energy)
                if dp[i - k] > 0:
                    current_energy = max(current_energy, dp[i - k])

        return max(dp)

class Solution:
    def maximumStrongPairXor(self, nums: List[int]) -> int:
        nums.sort()
        max_xor = 0
        j = 0

        for i in range(len(nums)):
            while j < len(nums) and nums[j] - nums[i] > nums[i]:
                j += 1
            for k in range(j, len(nums)):
                if abs(nums[k] - nums[i]) > min(nums[k], nums[i]):
                    break
                max_xor = max(max_xor, nums[k] ^ nums[i])

        return max_xor

class Solution:
    def isArraySpecial(self, nums: List[int], queries: List[List[int]]) -> List[bool]:
        n = len(nums)
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + (nums[i] % 2)

        ans = []
        for l, r in queries:
            odd_count = prefix[r + 1] - prefix[l]
            even_count = r - l + 1 - odd_count
            if odd_count > 0 and even_count > 0 and odd_count != even_count:
                ans.append(True)
            else:
                ans.append(False)
        return ans

class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        ans = 0
        left = 0

        for right in range(n):
            if nums[right] != k:
                left = right + 1
            else:
                count = 1
                while right + 1 < n and nums[right + 1] == k:
                    count += 1
                    right += 1
                ans += count * (count + 1) // 2

        return ans

class Solution:
    def numberOfArrays(self, differences: List[int], lower: int, upper: int) -> int:
        prefix_sum = list(accumulate(differences))
        min_val = min(prefix_sum)
        max_val = max(prefix_sum)
        start_range = max(lower - min_val, 0)
        end_range = min(upper - max_val, len(differences))
        return max(end_range - start_range + 1, 0)

class Solution:
    def missingElement(self, nums: List[int], k: int) -> int:
        n = len(nums)
        total_missing = nums[n - 1] - nums[0] - n + 1

        if k > total_missing:
            return nums[-1] + k - total_missing

        left, right = 0, n - 1
        while left < right:
            mid = (left + right) // 2
            missing = nums[mid] - nums[left] - (mid - left)
            if missing >= k:
                right = mid
            else:
                left = mid + 1
                k -= missing

        return nums[left - 1] + k

class Solution:
    def treeQueries(self, root: Optional[TreeNode], queries: List[int]) -> List[int]:
        depth = {}
        max_depth = {}

        def dfs(node, d):
            if not node:
                return -1
            depth[node.val] = d
            left = dfs(node.left, d + 1)
            right = dfs(node.right, d + 1)
            max_depth[node.val] = max(left, right) + 1
            return max(left, right) + 1

        dfs(root, 0)

        result = []
        for q in queries:
            if q == root.val:
                result.append(-1)
            else:
                parent_max_depth = max(max_depth[root.val], depth[q] - 1)
                result.append(parent_max_depth)

        return result

class Solution:
    def findSmallestRegion(self, regions: List[List[str]], region1: str, region2: str) -> str:
        parent = {}
        for region in regions:
            for i in range(1, len(region)):
                parent[region[i]] = region[0]

        ancestors = set()
        while region1 in parent:
            ancestors.add(region1)
            region1 = parent[region1]

        while region2 not in ancestors:
            region2 = parent[region2]

        return region2

