class Solution:
    def maximumTotalDamage(self, power: List[int]) -> int:
        count = Counter(power)
        keys = sorted(count.keys())
        n = len(keys)
        dp = [0] * n

        for i in range(n):
            dp[i] = keys[i] * count[keys[i]]
            if i > 0:
                dp[i] = max(dp[i], dp[i-1])
            if i > 1 and keys[i] - keys[i-1] > 2:
                dp[i] = max(dp[i], dp[i-1] + keys[i] * count[keys[i]])
            elif i > 1:
                dp[i] = max(dp[i], dp[i-2] + keys[i] * count[keys[i]])

        return dp[-1]

