class Solution:
    def minDistance(self, height: int, width: int, tree: List[int], squirrel: List[int], nuts: List[List[int]]) -> int:
        def distance(p1, p2):
            return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

        total_distance = 0
        first_nut_distance = float('inf')

        for nut in nuts:
            dist_to_tree = distance(nut, tree)
            total_distance += 2 * dist_to_tree
            first_nut_distance = min(first_nut_distance, dist_to_tree - distance(nut, squirrel))

        return total_distance + first_nut_distance

class Solution:
    def trap(self, height: List[int]) -> int:
        if not height:
            return 0

        left = 0
        right = len(height) - 1
        max_left = height[0]
        max_right = height[-1]
        water_trapped = 0

        while left < right:
            if height[left] < height[right]:
                water_trapped += max_left - height[left]
                max_left = max(max_left, height[left])
                left += 1
            else:
                water_trapped += max_right - height[right]
                max_right = max(max_right, height[right])
                right -= 1

        return water_trapped

class Solution:
    def shortestCommonSupersequence(self, str1: str, str2: str) -> str:
        m, n = len(str1), len(str2)

        # Create a 2D array to store lengths of longest common subsequence
        dp = [[0] * (n + 1) for _ in range(m + 1)]

        # Fill dp array
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if str1[i - 1] == str2[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1] + 1
                else:
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

        # Reconstruct the shortest common supersequence
        i, j = m, n
        result = []

        while i > 0 and j > 0:
            if str1[i - 1] == str2[j - 1]:
                result.append(str1[i - 1])
                i -= 1
                j -= 1
            elif dp[i - 1][j] > dp[i][j - 1]:
                result.append(str1[i - 1])
                i -= 1
            else:
                result.append(str2[j - 1])
                j -= 1

        # Add remaining characters of str1
        while i > 0:
            result.append(str1[i - 1])
            i -= 1

        # Add remaining characters of str2
        while j > 0:
            result.append(str2[j - 1])
            j -= 1

        # The result is built backwards, so reverse it
        return ''.join(result[::-1])

