class Solution:
    def widestPairOfIndices(self, nums1: List[int], nums2: List[int]) -> int:
        prefix1 = []
        prefix2 = []
        max_dist = 0

        # Calculate prefix sums for both arrays
        for num1, num2 in zip(nums1, nums2):
            prefix1.append(prefix1[-1] + num1 if prefix1 else num1)
            prefix2.append(prefix2[-1] + num2 if prefix2 else num2)

        # Use a dictionary to store the difference of prefix sums
        diff_dict = {}

        for i in range(len(prefix1)):
            current_diff = prefix1[i] - prefix2[i]
            if current_diff in diff_dict:
                max_dist = max(max_dist, i - diff_dict[current_diff])
            else:
                diff_dict[current_diff] = i

        return max_dist

