class Solution:
    def sumFourDivisors(self, nums: List[int]) -> int:
        ans = 0

        for num in nums:
            count = 0
            for i in range(1, int(num**0.5)+1):
                if num % i == 0:
                    count += 1
                    if i != num // i:
                        count += 1

            if count == 4:
                ans += num + (num//i)

        return ans

from collections import Counter

class Solution:
    def minimumIndex(self, nums: List[int]) -> int:
        count = Counter(nums)
        target_count = len(nums) // 2

        for i in range(len(nums)):
            if count[nums[i]] >= target_count:
                left_count = sum(1 for num in nums[:i+1])
                right_count = sum(1 for num in nums[i+1:])

                if left_count * count[nums[i]] > target_count and right_count * count[nums[i]] > target_count:
                    return i

        return -1

class Solution:
    def minDeletionSize(self, strs: List[str]) -> int:
