class Solution:
    def shortestCommonSupersequence(self, str1: str, str2: str) -> str:
        m, n = len(str1), len(str2)
        dp = [[""] * (n + 1) for _ in range(m + 1)]

        # Fill the dp table
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if str1[i - 1] == str2[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1] + str1[i - 1]
                else:
                    if len(dp[i - 1][j]) > len(dp[i][j - 1]):
                        dp[i][j] = dp[i - 1][j]
                    else:
                        dp[i][j] = dp[i][j - 1]

        # Reconstruct the shortest common supersequence
        scs = []
        i, j = m, n
        while i > 0 and j > 0:
            if str1[i - 1] == str2[j - 1]:
                scs.append(str1[i - 1])
                i -= 1
                j -= 1
            elif len(dp[i - 1][j]) > len(dp[i][j - 1]):
                scs.append(str1[i - 1])
                i -= 1
            else:
                scs.append(str2[j - 1])
                j -= 1

        # Add remaining characters
        while i > 0:
            scs.append(str1[i - 1])
            i -= 1
        while j > 0:
            scs.append(str2[j - 1])
            j -= 1

        return ''.join(reversed(scs))

class Solution:
    def minimumLength(self, s: str) -> int:
        stack = []
        for char in s:
            if stack and stack[-1] == char:
                stack.pop()
            else:
                stack.append(char)
        return len(stack)

class Solution:
    def nextGreaterElement(self, n: int) -> int:
        s = str(n)
        for i in range(len(s)-2, -1, -1):
            if s[i] < s[i+1]:
                break
        else:
            return -1

        j = len(s)-1
        while s[j] <= s[i]:
            j -= 1

        s[i], s[j] = s[j], s[i]
        s[i+1:] = sorted(s[i+1:])

        ans = int(''.join(s))
        return ans if ans > n else -1

class Solution:
    def maxDistance(self, arrays: List[List[int]]) -> int:
        n = len(arrays)
        max_distance = 0

        for i in range(n):
            for j in range(i + 1, n):
                max_distance = max(max_distance, abs(arrays[i][-1] - arrays[j][0]))

        return max_distance

from typing import List

class Solution:
    def sumFourDivisors(self, nums: List[int]) -> int:
        def count_divisors(n):
            if n < 4:
                return 0
            count = 2  # 1 and n itself are always divisors
            for i in range(2, int(n**0.5) + 1):
                if n % i == 0:
                    count += 1
                    if i != n // i:
                        count += 1
            return count

        total_sum = 0
        for num in nums:
            if count_divisors(num) == 2:
                total_sum += sum(i for i in range(1, num + 1) if num % i == 0)

        return total_sum

class Solution:
    def checkPartitioning(self, s: str) -> bool:
        n = len(s)
        dp = [[False] * (n+1) for _ in range(n+1)]

        # Base case: a single character is always a palindrome
        for i in range(n):
            dp[i][i] = True

        # Fill the dp table
        for length in range(2, n+1):
            for start in range(n-length+1):
                end = start + length - 1
                if s[start] == s[end]:
                    dp[start][end] = dp[start+1][end-1]

        # Check all possible partitions
        for i in range(n):
            if dp[0][i] and dp[i+1][n-1]:
                return True
        return False

class Solution:
    def minimumSubstringsInPartition(self, s: str) -> int:
        def is_balanced(s):
            count = {}
            for char in s:
                if char in count:
                    count[char] += 1
                else:
                    count[char] = 1
            return len(set(count.values())) == 1

        count = 0
        i = 0
        while i < len(s):
            j = i
            while j < len(s) and is_balanced(s[i:j+1]):
                j += 1
            count += 1
            i = j
        return count

class Solution:
    def minimumSteps(self, s: str) -> int:
        steps = 0
        count_ones = 0

        for i, char in enumerate(s):
            if char == '1':
                steps += i - count_ones
                count_ones += 1

        return steps

