class Solution:
    def subtreeWithAllDeepest(self, root: Optional[TreeNode]) -> Optional[TreeNode]:
        def dfs(node):
            if not node:
                return None, 0

            left_node, left_depth = dfs(node.left)
            right_node, right_depth = dfs(node.right)

            if left_depth > right_depth:
                return left_node, left_depth + 1
            elif left_depth < right_depth:
                return right_node, right_depth + 1
            else:
                return node, left_depth + 1

        return dfs(root)[0]

class Solution:
    def isValid(self, s: str) -> bool:
        # Check if the length of the string is less than 3
        if len(s) < 3:
            return False

        # Iterate through the string
        for i in range(len(s)):
            # Check if the current character is not 'a' or 'b'
            if s[i] != 'a' and s[i] != 'b':
                # Check if the next character is 'a' or 'b'
                if s[i+1] != 'a' and s[i+1] != 'b':
                    # If the condition is met, return False
                    return False

        # If all conditions are met, return True
        return True

