class Solution:
    def longestUnivaluePath(self, root: Optional[TreeNode]) -> int:
        self.result = 0

        def helper(node):
            if not node:
                return 0

            left_length = helper(node.left)
            right_length = helper(node.right)

            left_arrow = right_arrow = 0

            if node.left and node.left.val == node.val:
                left_arrow = left_length + 1
            if node.right and node.right.val == node.val:
                right_arrow = right_length + 1

            self.result = max(self.result, left_arrow + right_arrow)

            return max(left_arrow, right_arrow)

        helper(root)
        return self.result

class Solution:
    def largest1BorderedSquare(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        dp_top = [[0] * n for _ in range(m)]
        dp_left = [[0] * n for _ in range(m)]

        max_side = 0

        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    dp_top[i][j] = dp_top[i-1][j] + 1 if i > 0 else 1
                    dp_left[i][j] = dp_left[i][j-1] + 1 if j > 0 else 1

                    side = min(dp_top[i][j], dp_left[i][j])
                    while side > max_side:
                        if dp_top[i-side+1][j] >= side and dp_left[i][j-side+1] >= side:
                            max_side = side
                            break
                        side -= 1

        return max_side ** 2

class Solution:
    def maximumGain(self, s: str, x: int, y: int) -> int:
        if x < y:
            return self.maximumGain(s[::-1], y, x)
        stack = []
        result = 0
        for char in s:
            if stack and stack[-1] == 'a' and char == 'b':
                stack.pop()
                result += x
            else:
                stack.append(char)
        s = ''.join(stack)
        stack = []
        for char in s[::-1]:
            if stack and stack[-1] == 'b' and char == 'a':
                stack.pop()
                result += y
            else:
                stack.append(char)
        return result

class Solution:
    def mySqrt(self, x: int) -> int:
        if x < 0:
            raise ValueError("Input must be non-negative.")

        left, right = 0, x
        while left <= right:
            mid = (left + right) // 2
            if mid * mid == x:
                return mid
            elif mid * mid < x:
                left = mid + 1
            else:
                right = mid - 1

        return left

# Definition for a binary tree node.
