class Solution:
    def minMoves(self, nums: List[int], limit: int) -> int:
        n = len(nums)
        max_val = 2 * limit
        dp = [0] * (max_val + 1)

        for i in range(n // 2):
            low = min(nums[i], nums[n - 1 - i]) + 1
            high = max(nums[i], nums[n - 1 - i]) + limit
            dp[low] += 1
            dp[high + 1] -= 1

        for i in range(1, max_val + 1):
            dp[i] += dp[i - 1]

        return min(dp[2 : 2 * limit + 1])

class Solution:
    def countExcellentPairs(self, nums: List[int], k: int) -> int:
        ans = 0
        for i in range(len(nums)):
            for j in range(i+1, len(nums)):
                if bin(nums[i]).count('1') + bin(nums[j]).count('1') >= k:
                    ans += 1
        return ans

