class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def closestNodes(self, root: Optional[TreeNode], queries: List[int]) -> List[List[int]]:
        result = []
        for q in queries:
            mini = float('-inf')
            maxi = float('inf')
            current = root
            while current:
                if current.val == q:
                    mini = maxi = current.val
                    break
                elif current.val < q:
                    mini = max(mini, current.val)
                    current = current.right
                else:
                    maxi = min(maxi, current.val)
                    current = current.left
            result.append([mini if mini != float('-inf') else -1, maxi if maxi != float('inf') else -1])
        return result

