class Solution:
    def validateBinaryTreeNodes(self, n: int, leftChild: List[int], rightChild: List[int]) -> bool:
        visited = set()
        root_candidates = set(range(n))

        for i in range(n):
            if leftChild[i] != -1:
                if leftChild[i] in root_candidates:
                    root_candidates.remove(leftChild[i])
                else:
                    return False
                if leftChild[i] in visited:
                    return False
                visited.add(leftChild[i])
            if rightChild[i] != -1:
                if rightChild[i] in root_candidates:
                    root_candidates.remove(rightChild[i])
                else:
                    return False
                if rightChild[i] in visited:
                    return False
                visited.add(rightChild[i])

        return len(root_candidates) == 1 and len(visited) == n

class Solution:
    def equalCountSubstrings(self, s: str, count: int) -> int:
        ans = 0
        n = len(s)
        for i in range(n):
            count_dict = {}
            for j in range(i, n):
                char = s[j]
                if char not in count_dict:
                    count_dict[char] = 1
                else:
                    count_dict[char] += 1
                if count_dict[char] == count:
                    ans += 1
        return ans

