class Solution:
    def isPossible(self, nums: List[int]) -> bool:
        count = Counter(nums)
        tail = []
        for num in nums:
            if count[num] == 0:
                continue
            count[num] -= 1
            if tail and tail[-1] + 1 < num:
                return False
            if tail and tail[-1] == num:
                tail.pop()
            else:
                tail.append(num)
        return len(tail) >= 3

