class Solution:
    def kthLargestLevelSum(self, root: Optional[TreeNode], k: int) -> int:
        if not root:
            return -1

        level_sum = []
        queue = [root]

        while queue:
            current_level_sum = 0
            for _ in range(len(queue)):
                node = queue.pop(0)
                current_level_sum += node.val
                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)
            level_sum.append(current_level_sum)

        if len(level_sum) < k:
            return -1

        heapq.heapify(level_sum)
        for _ in range(k - 1):
            heapq.heappop(level_sum)

        return level_sum[0]

class Solution:
    def minSwaps(self, s: str) -> int:
        balance = 0
        swaps = 0

        for char in s:
            if char == '[':
                balance += 1
            else:
                balance -= 1

            # If balance goes negative, we need to swap a '['
            if balance < 0:
                balance += 2
                swaps += 1

        return swaps

class Solution:
    def minOperations(self, n: int) -> int:
        count = 0
        while n != 0:
            if n & 1 == 1:
                count += 1
            n >>= 1
        return count

from collections import defaultdict

class Solution:
    def calcEquation(self, equations: List[List[str]], values: List[float], queries: List[List[str]]) -> List[float]:
        graph = defaultdict(dict)
        for (A, B), value in zip(equations, values):
            graph[A][B] = value
            graph[B][A] = 1 / value

        def dfs(start, end, visited):
            if start not in graph or end not in graph:
                return -1.0
            if start == end:
                return 1.0
            visited.add(start)
            for neighbor in graph[start]:
                if neighbor not in visited:
                    result = dfs(neighbor, end, visited)
                    if result != -1.0:
                        return graph[start][neighbor] * result
            visited.remove(start)
            return -1.0

        results = []
        for query in queries:
            results.append(dfs(query[0], query[1], set()))

        return results

class Solution:
    def largestSubmatrix(self, matrix: List[List[int]]) -> int:
        m, n = len(matrix), len(matrix[0])
        heights = [matrix[i][:] for i in range(m)]

        for j in range(1, n):
            for i in range(m):
                if matrix[i][j] == 1:
                    heights[i][j] += heights[i][j - 1]

        max_area = 0
        for row in heights:
            row.sort(reverse=True)
            for k in range(n):
                max_area = max(max_area, row[k] * (k + 1))

        return max_area

class Solution:
    def movesToStamp(self, stamp: str, target: str) -> List[int]:
        m, n = len(stamp), len(target)
        dp = [[float('inf')] * (n + 1) for _ in range(m + 1)]
        dp[0][0] = 0

        # Fill the DP table
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if target[j - 1] == stamp[i - 1]:
                    dp[i][j] = min(dp[i][j], dp[i - 1][j - 1])
                else:
                    dp[i][j] = min(dp[i][j], dp[i - 1][j])

        # Backtrack to find the path
        result = []
        i, j = m, n
        while i > 0 and j > 0:
            if target[j - 1] == stamp[i - 1]:
                result.append(j - 1)
                i -= 1
                j -= 1
            elif dp[i - 1][j] < dp[i][j]:
                i -= 1
            else:
                j -= 1

        # Reverse the result
        result.reverse()

        # Check if the result is valid
        if dp[m][n] != 0:
            return []

        return result

from collections import defaultdict

class Solution:
    def taskSchedulerII(self, tasks: List[int], space: int) -> int:
        last_time = defaultdict(int)
        total_days = 0

        for task in tasks:
            if task not in last_time or total_days - last_time[task] > space:
                last_time[task] = total_days
                total_days += 1
            else:
                # Calculate the time needed to wait until the next available slot
                wait_time = max(last_time[task] + space - total_days, 1)
                total_days += wait_time
                last_time[task] = total_days

        return total_days

from typing import List

class Solution:
    def minimumValueSum(self, nums: List[int], andValues: List[int]) -> int:
        n, m = len(nums), len(andValues)

        # Helper function to check if we can split nums[:i+1] into k subarrays
        # with the required AND values
        def can_split(i, k):
            if k == 0:
                return i == -1
            if i < k - 1:
                return False

            current_and = nums[i]
            for j in range(i, k - 2, -1):
                current_and &= nums[j]
                if current_and == andValues[k - 1]:
                    if can_split(j - 1, k - 1):
                        return True
            return False

        # Try to find the minimum possible sum of the values of the m subarrays
        def find_min_sum(i, k):
            if k == 0:
                return nums[i + 1] if i >= 0 else 0
            if i < k - 1:
                return float('inf')

            current_and = nums[i]
            min_sum = float('inf')
            for j in range(i, k - 2, -1):
                current_and &= nums[j]
                if current_and == andValues[k - 1]:
                    min_sum = min(min_sum, nums[j + 1] + find_min_sum(j - 1, k - 1))
            return min_sum

        if not can_split(n - 1, m):
            return -1

        return find_min_sum(n - 1, m)

class Solution:
    def minimumValueSum(self, nums: List[int], andValues: List[int]) -> int:
        n, m = len(nums), len(andValues)
        if reduce(lambda x, y: x & y, nums) != 0:
            return -1

        dp = [float('inf')] * (n + 1)
        dp[0] = 0
        prefix_and = [0] * (n + 1)

        for i in range(1, n + 1):
            prefix_and[i] = prefix_and[i - 1] & nums[i - 1]

        for i in range(m - 1, -1, -1):
            target_and = andValues[i]
            j = n - 1
            while j >= 0 and prefix_and[j] & nums[j] != target_and:
                j -= 1

            if j == -1:
                return -1

            for k in range(j, -1, -1):
                dp[k] = min(dp[k], dp[j + 1] + sum(nums[k:j + 1]))

        return dp[0]

class Solution:
    def resultGrid(self, image: List[List[int]], threshold: int) -> List[List[int]]:
        m, n = len(image), len(image[0])
        result = [[image[i][j] for j in range(n)] for i in range(m)]

        def is_valid_region(i, j):
            for dx in range(-1, 2):
                for dy in range(-1, 2):
                    if 0 <= i + dx < m and 0 <= j + dy < n:
                        if abs(image[i][j] - image[i + dx][j + dy]) > threshold:
                            return False
            return True

        def get_region_intensity(i, j):
            total_intensity = 0
            count = 0
            for dx in range(-1, 2):
                for dy in range(-1, 2):
                    if 0 <= i + dx < m and 0 <= j + dy < n:
                        total_intensity += image[i + dx][j + dy]
                        count += 1
            return total_intensity // count

        for i in range(1, m - 1):
            for j in range(1, n - 1):
                if is_valid_region(i, j):
                    region_intensity = get_region_intensity(i, j)
                    result[i][j] = region_intensity

        return result

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def treeQueries(self, root: Optional[TreeNode], queries: List[int]) -> List[int]:
        depth = {}
        height = {}

        def dfs(node, d):
            if not node:
                return -1
            depth[node.val] = d
            h = max(dfs(node.left, d + 1), dfs(node.right, d + 1)) + 1
            height[node.val] = h
            return h

        dfs(root, 0)

        levels = defaultdict(list)
        for node, d in depth.items():
            levels[d].append((-height[node], node))
            levels[d].sort()
            if len(levels[d]) > 2:
                levels[d].pop()

        ans = []
        for q in queries:
            d = depth[q]
            if len(levels[d]) == 1:
                ans.append(d - 1)
            elif levels[d][0][1] == q:
                ans.append(-levels[d][1][0] + d)
            else:
                ans.append(-levels[d][0][0] + d)

        return ans

class Solution:
    def squareIsWhite(self, coordinates: str) -> bool:
        return (ord(coordinates[0]) - ord('a')) % 2 == 0

class Solution:
    def getMaxLen(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0

        left = 0
        right = 0
        max_len = 0

        while right < n:
            if nums[right] > 0:
                max_len = max(max_len, right - left + 1)
                while left < right and nums[left] < 0:
                    left += 1
                right += 1
            else:
                right += 1

        return max_len

class Solution:
    def minimumString(self, a: str, b: str, c: str) -> str:
        def merge(x, y):
            if y in x:
                return x
            for i in range(len(y)):
                if x.endswith(y[:i]):
                    return x + y[i:]
            return x + y

        candidates = [
            merge(merge(a, b), c),
            merge(merge(a, c), b),
            merge(merge(b, a), c),
            merge(merge(b, c), a),
            merge(merge(c, a), b),
            merge(merge(c, b), a)
        ]

        min_length = min(len(candidate) for candidate in candidates)
        result = min((candidate for candidate in candidates if len(candidate) == min_length))

        return result

