import collections

class Solution:
    def avoidFlood(self, rains: List[int]) -> List[int]:
        res = [-1] * len(rains)
        seen = set()
        full_lakes = collections.defaultdict(list)
        for i, r in enumerate(rains):
            if r != 0:
                if r in seen:
                    return []
                seen.add(r)
                full_lakes[r].append(i)
            else:
                available = full_lakes.pop(r, [])
                if not available:
                    return []
                res[available.pop()] = i + 1
        return res

class Solution:
    def makeIntegerBeautiful(self, n: int, target: int) -> int:
        def digit_sum(num):
            return sum(int(digit) for digit in str(num))

        if digit_sum(n) <= target:
            return 0

        str_n = str(n)
        length = len(str_n)

        for i in range(length):
            if digit_sum(int(str_n[:i] + '0' * (length - i))) <= target:
                return int(str_n[:i] + '0' * (length - i)) - n

        return 0

class Solution:
    def minSwaps(self, s: str) -> int:
