class Solution:
    def longestWord(self, words: List[str]) -> str:
        trie = {}
        for word in sorted(words):
            node = trie
            for char in word:
                if char not in node:
                    node[char] = {}
                node = node[char]
            node['end'] = word

        def dfs(node, path):
            if 'end' in node:
                nonlocal res
                if len(node['end']) > len(res) or (len(node['end']) == len(res) and node['end'] < res):
                    res = node['end']
            for char in node:
                if char != 'end':
                    dfs(node[char], path + char)

        res = ''
        dfs(trie, '')
        return res

from collections import defaultdict, deque
from typing import List

class Solution:
    def magnificentSets(self, n: int, edges: List[List[int]]) -> int:
        # Build the graph
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        # Function to check if a component is bipartite
        def is_bipartite(start):
            color = [0] * (n + 1)
            queue = deque([start])
            color[start] = 1

            while queue:
                node = queue.popleft()
                for neighbor in graph[node]:
                    if color[neighbor] == 0:
                        color[neighbor] = -color[node]
                        queue.append(neighbor)
                    elif color[neighbor] == color[node]:
                        return False
            return True

        # Function to get the maximum depth of BFS
        def max_depth(start):
            visited = set()
            queue = deque([(start, 0)])
            visited.add(start)

            while queue:
                node, depth = queue.popleft()
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        queue.append((neighbor, depth + 1))
            return depth

        # Check each connected component
        groups = 0
        visited = set()
        for i in range(1, n + 1):
            if i not in visited:
                if not is_bipartite(i):
                    return -1
                component_max_depth = 0
                for node in range(1, n + 1):
                    if node not in visited and is_bipartite(node):
                        component_max_depth += max_depth(node)
                        for neighbor in graph[node]:
                            visited.add(neighbor)
                groups += component_max_depth

        return groups

class Solution:
    def numberOfArrays(self, s: str, k: int) -> int:
        MOD = 10**9 + 7

        n = len(s)
        dp = [0] * (n + 1)
        dp[0] = 1

        for i in range(1, n + 1):
            num = 0
            for j in range(i - 1, -1, -1):
                num = num * 10 + int(s[j])
                if num > k:
                    break
                dp[i] = (dp[i] + dp[j]) % MOD

        return dp[n]

from typing import List

class Solution:
    def minDistance(self, height: int, width: int, tree: List[int], squirrel: List[int], nuts: List[List[int]]) -> int:
        def distance(p1, p2):
            return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

        total_distance = 0
        max_save = float('-inf')

        for nut in nuts:
            total_distance += 2 * distance(tree, nut)
            save = distance(squirrel, nut) - distance(tree, nut)
            max_save = max(max_save, save)

        return total_distance - max_save

class Solution:
    def satisfiesConditions(self, grid: List[List[int]]) -> bool:
        # Iterate through the grid starting from the second row and ending at the second last row
        for i in range(1, len(grid)):
            # Iterate through each element in the current row
            for j in range(len(grid[i])):
                # Check if the current element is equal to the element below it
                if grid[i][j] != grid[i + 1][j]:
                    # If they are not equal, return False
                    return False
        # If all elements are equal, return True
        return True

class Solution:
    def possibleBipartition(self, n: int, dislikes: List[List[int]]) -> bool:
        # Initialize two sets for each group
        group1 = set()
        group2 = set()

        # Helper function to check if the graph can be divided into two groups
        def dfs(node, color):
            if node in group1:
                return False
            if node in group2:
                return True

            # Mark the current node as visited
            group1.add(node)
            group2.add(node)

            # Check all neighbors of the current node
            for neighbor in dislikes[node]:
                if dfs(neighbor, -color):
                    return False

            return True

        # Try to partition the graph into two groups
        for i in range(1, n + 1):
            if not dfs(i, 1):  # Start DFS from node i with color 1
                return False

        return True

class Solution:
    def averageValue(self, nums: List[int]) -> int:
        return sum(nums) // len(nums) if sum(nums) % 3 == 0 else 0

class Solution:
    def maxProductPath(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        dp = [[0] * n for _ in range(m)]
        dp[0][0] = grid[0][0]

        for i in range(1, m):
            for j in range(1, n):
                if grid[i][j] >= 0:
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]) * grid[i][j]
                else:
                    dp[i][j] = min(dp[i - 1][j], dp[i][j - 1]) * grid[i][j]

        return dp[-1][-1] % (10**9 + 7)
